query ReturnPolicyReconciliation($pageAfter: String, $redirectAfter: String) {
  shop {
    id name
    shopPolicies { id type title body url updatedAt }
  }
  pages(first: 50, after: $pageAfter, query: "handle:return-policy") {
    nodes { id title handle body isPublished publishedAt updatedAt templateSuffix }
    pageInfo { hasNextPage endCursor }
  }
  urlRedirects(first: 50, after: $redirectAfter, query: "path:/pages/return-policy") {
    nodes { id path target }
    pageInfo { hasNextPage endCursor }
  }
}

